# 第 5 批：卦 36-44（明夷、家人、睽、蹇、解、损、益、夬、姤）

HEXAGRAMS = {
  "36": {"zh": "明夷卦下离上坤，光明沉入地中。它讲的是光明受遮蔽的时候——把光芒藏起来，但保住自己内心的明。", "en": "Mingyi is clarity below, earth above — light sinking into the ground. It's about when light is obscured: hide your brightness, but keep the clarity in your heart.", "ja": "明夷は下が離、上が坤。明かりが地の中へ入る。明が覆われる時を表す——その光を隠し、しかし心の明は保つ。"},
  "37": {"zh": "家人卦下离上巽，讲家道。它讲的是治家之道——把家端正，靠的是严厉与和睦相互配合。", "en": "Jia ren is clarity below, compliance above — the way of the household. It's about ordering a home: setting it right takes strictness and harmony working together.", "ja": "家人は下が離、上が巽。家の道。家を正すことを表す——厳しさと和やかさが助け合って家を治める。"},
  "38": {"zh": "睽卦下兑上离，两女同居、志向不同。它讲的是乖离——在分离中看到相同，在差异中看到相通。", "en": "Kui is joy below, clarity above — two women dwelling together, aims apart. It's about divergence: within separation see the common, within difference see the connection.", "ja": "睽は下が兑、上が離。二人の女が同じ家にいて志が違う。離れることを表す——離れる中に同じものを見いだし、違う中に通じるものを見る。"},
  "39": {"zh": "蹇卦下艮上坎，行路有险。它讲的是见险能止——蹇的时候，往西南有利、往东北不利，方位比喻进退。", "en": "Jian is mountain below, danger above — a perilous road. It's about stopping when you see danger: in Jian, southwest is favorable, northeast not — directions image advance and retreat.", "ja": "蹇は下が艮、上が坎。道に険がある。険を見て止められることを表す——蹇の時は西南が利し、東北は利せず。方角は進退をたとえたもの。"},
  "40": {"zh": "解卦下坎上震，险难解除。它讲的是化解纷争——解了之后才行动，用安静来驾驭变动。", "en": "Xie is danger below, movement above — difficulty released. It's about resolving entanglement: act only after release, and master motion with stillness.", "ja": "解は下が坎、上が震。険が解ける。もつれを解くことを表す——解けてから動き、静でもって動を制する。"},
  "41": {"zh": "损卦下兑上艮，减损下面、增益上面。它讲的是损己——损了又损，克制忿怒、堵住欲望，损己而有诚。", "en": "Sun is joy below, mountain above — decreasing below, increasing above. It's about reducing yourself: less and less, curb anger and block desire, decreasing with sincerity.", "ja": "損は下が兑、上が艮。下を損して上を益す。自らを減らすことを表す——損にまた損、怒りを制し欲をふさぎ、誠をもって損する。"},
  "42": {"zh": "益卦下震上巽，减损上面、增益下面。它讲利人——见善就学，有过就改，益人就是益己。", "en": "Yi is movement below, compliance above — decreasing above, increasing below. It's about benefiting others: see good and adopt it, have fault and correct it — benefiting others is benefiting yourself.", "ja": "益は下が震、上が巽。上を損して下を益す。人を利することを表す——善を見れば移り、過ちあれば改める。人を益すのは自らを益すことだ。"},
  "43": {"zh": "夬卦下乾上兑，决断而去。它讲的是决断——要清除就果断清除，但必须靠众人的正，不可偏私。", "en": "Guai is strength below, joy above — deciding and removing. It's about decision: remove decisively, but only through the right of the many, never one-sided.", "ja": "夬は下が乾、上が兑。決して除く。決断を表す——除くなら決然と除くが、衆の正によるべきで、偏ってはならない。"},
  "44": {"zh": "姤卦下巽上乾，不期而遇。它讲的是邂逅——像用金柅系住，不期而遇的时候，礼节要先立。", "en": "Gou is compliance below, strength above — meeting unexpectedly. It's about encounter: like tied to a metal brake, when meeting unplanned, set courtesy first.", "ja": "姤は下が巽、上が乾。期せずして遇う。めぐり合いを表す——金の柅につなぐように、期せぬ出会いには礼を先に立てる。"},
}

LINES = {
  # 36 明夷
  "36-0": {"zh": "你在最底下，光明开始受伤，行动要快，垂下翅膀来隐藏。明既受伤就不能显露——收起翅膀快走，虽困却不失其道。", "en": "You're at the bottom, the light first wounded — move fast, folding your wings to hide. Once light is hurt it can't show. Fold your wings and hurry; though hard-pressed, you don't lose your way.", "ja": "一番下にいて、明かりが傷つき始めた。動きは速く、翼を垂れて隠す。明は傷つけば現せない。翼を畳んで急げ——困っても道を失わない。"},
  "36-1": {"zh": "你在下卦正中，柔顺得正而受伤不深，得到壮马相助。伤得浅、救得快，就能恢复——柔顺得中，所以得到帮助。", "en": "You're at the center of the lower trigram, soft and proper, only slightly wounded, helped by a strong horse. Hurt shallow and rescued quickly, you can recover. Soft and centered, you gain help.", "ja": "下卦の中央にいて、柔らかく正しく傷は浅く、強い馬の助けを得る。傷が浅く救いが早ければ、回復できる。柔順で中を得たので、助けが得られる。"},
  "36-2": {"zh": "你在下卦最上面，刚正而处明夷之中，可以有所作为。除大害不能急——刚而能审，这才是正当之道。", "en": "You're at the top of the lower trigram, rigid and upright amidst Mingyi, able to accomplish. Removing a great harm can't be hasty — strong yet discerning: that's the right way.", "ja": "下卦の最上部にいて、剛正で明夷の中にあり、何か成せる。大害を除くには急いではならない。剛で審えることができれば、それが正しい道だ。"},
  "36-3": {"zh": "你在上卦下面，柔顺得正而进入暗地，了解到实情后离去。进到里面知其内情，就可以決然离开——看出苗头就行动，不等一天过完。", "en": "You're below the upper trigram, soft and proper, entering the dark place, learning the truth and leaving. Once inside you know the situation and can decide to go. See the sign and act — don't wait out the day.", "ja": "上卦の下にいて、柔らかく正しく闇の場所へ入り、実情を知って去る。内に入って事情を知れば、去ることを決められる。兆しを見て動き、一日を待たない。"},
  "36-4": {"zh": "你在尊位，柔和中正而处黑暗之极，把光明藏起来自守。处在暗世而能隐藏光明，这是箕子的道理——光明不会熄灭，所以守着它就行。", "en": "You're in the place of honor, soft and centered at the depth of darkness, hiding your light to keep yourself. In a dark age, hiding your light is Jizi's way. Light can't be extinguished — so just hold it.", "ja": "尊い位にいて、柔らかく中を得て闇の極にあり、明を隠して自らを守る。闇の世に明を隠せるのは箕子の道だ。明は滅びない。ただ守ればよい。"},
  "36-5": {"zh": "你到了卦的顶，明夷的终点，光明完全熄灭。本来明却终于暗，是自己失了明——居高而不知隐藏，所以坠落得很快。", "en": "You're at the top of the hexagram, Mingyi at its end, your light utterly extinguished. Bright by nature yet ending dark, you lost your own light. High up but not knowing to hide, you fall quickly.", "ja": "卦の頂点にいて、明夷の終わり。明かりがすっかり消えた。もとは明るかったのに闇に終わったのは、自ら明を失ったから。高いのに隠すことを知らないので、早く落ちる。"},
  # 37 家人
  "37-0": {"zh": "你在最底下，是治家的开始，一开始就要立下规矩。治家贵在谨慎开头——防患于未然，后面就没变故，悔恨可消。", "en": "You're at the bottom, the start of managing a household — set boundaries from the outset. Managing a home values a careful start: prevent trouble before it arises and no change comes later; regret disappears.", "ja": "一番下にいて、家を治める初め。最初に防ぎを立てる。家を治めるのは初めを慎むことが肝心——未然に防げば後で変わりがなく、悔いも消える。"},
  "37-1": {"zh": "你在下卦正中，柔顺得正而主内事，不独揽其成。主内而不独占功劳，是妇人的正道——柔中自守，家就能齐。", "en": "You're at the center of the lower trigram, soft and proper, presiding inside without claiming sole credit. Presiding within without monopolizing the achievement is a woman's rightness. Soft and centered, the household is ordered.", "ja": "下卦の中央にいて、柔らかく正しく内を主るが、功を独り占めしない。内を主って成就を独りしないのは、婦人の正だ。柔中を守れば、家は整う。"},
  "37-2": {"zh": "你在下卦最上面，过于刚严，治家过严但最终得宜。治家宁可过严，不可过狎——严了人怕而事立，狎了终究乱。", "en": "You're at the top of the lower trigram — too rigid and strict — managing too harshly yet ending well. Better too strict than too familiar in managing a home: strictness makes people heed and things stand; familiarity ends in disorder.", "ja": "下卦の最上部にいて、剛すぎて厳しく、家を治めるのが厳しすぎるが終わりは宜しい。家を治めるには厳しすぎるくらいでよく、馴れすぎてはならない。厳しければ人は畏れ事が立ち、馴れれば終わりに乱れる。"},
  "37-3": {"zh": "你在上卦下面，柔顺得正而能保家之富。有家而能守其富，在于柔顺得正——富而不骄，是保家之道。", "en": "You're below the upper trigram, soft and proper, able to keep your household's wealth. Having a home and preserving its wealth lies in softness and rightness — rich without arrogance: the way to keep a home.", "ja": "上卦の下にいて、柔らかく正しく家の富を保てる。家を持って富を守れるのは、柔顺で正を得ているから。富んで驕らない——これが家を保つ道だ。"},
  "37-4": {"zh": "你身居尊位，刚健中正，把治家之道推及天下。君主能正其家，天下就被感化——不用忧劳而自有成。", "en": "You're in the place of honor, strong and centered, extending the household way to the world. A ruler who sets his own house right transforms the world. Without worry or toil, achievement comes.", "ja": "尊い位にいて、剛中で正しく、家を治める道を天下及ぼす。君がその家を正せば、天下は化される。憂え労さずとも、自ずと成る。"},
  "37-5": {"zh": "你到了卦的顶，是治家的终点，用诚与威守住长久。治家之久，在于诚与威并行——威由信而生，所以能有好终。", "en": "You're at the top of the hexagram, managing a home at its end, keeping it long with sincerity and dignity. Lasting management means sincerity and authority together. Authority arises from trust, so there's a good end.", "ja": "卦の頂点にいて、家を治める終わり。誠と威でその久しさを保つ。家を長く治めるには誠と威が並ぶこと。威は信から生まれるので、良い終わりがある。"},
  # 38 睽
  "38-0": {"zh": "你在最底下，是睽的开始，失去的东西不找自己回来。乖异之时，东西不求自还——能容纳所厌恶的，怨恨就能解开。", "en": "You're at the bottom, the start of Kui — what you lost returns without seeking. In divergence, things come back unasked. If you can accept what you dislike, resentment can be released.", "ja": "一番下にいて、睽の初め。失ったものを求めずに自ら戻る。離れている時、物は求めずとも返る。嫌うところを容れられれば、怨みは解ける。"},
  "38-1": {"zh": "你在下卦正中，与六五相应却有乖隔，委曲以求相遇。处乖离之时不能直来直去——委曲相求，是通权达变之道。", "en": "You're at the center of the lower trigram, matched with the sixth line yet separated — winding your way to meet. In divergence you can't go straight. Winding to seek each other is the way of adapting.", "ja": "下卦の中央にいて、六五に応じるが乖き、くねくねと巡り合いを求める。乖離の時はまっすぐ行けない。委曲して求めるのが、権変に通じる道だ。"},
  "38-2": {"zh": "你在下卦最上面，不中不正，夹在两个刚爻之间被牵制。处境不安又被人制约，起初很困——守正等待，所以能有好终。", "en": "You're at the top of the lower trigram — off-center and improper — caught between two rigid lines and restrained. Uneasy and controlled by others, at first hard-pressed. Hold to rightness and wait, so you reach a good end.", "ja": "下卦の最上部にいて、中も正も外れ、二つの剛の間で引き留められる。居所が安まらず人に制され、初めは非常に困る。正を守って待つので、良い終わりを得る。"},
  "38-3": {"zh": "你在上卦下面，孤立无应，与初九同德而相交相信。孤立之时，得同志者相交相信就能渡过——虽危却不孤单。", "en": "You're below the upper trigram, isolated without a match, but joined in trust with the first line of like virtue. In isolation, finding a like-minded one to trust carries you through. Though endangered, you're not alone.", "ja": "上卦の下にいて、孤立して応えもないが、初九と徳を同じくして信じ合う。孤立の時、志を同じくする者と信じ合えば救われる。危うくても孤りではない。"},
  "38-4": {"zh": "你在尊位，柔和中正而下应九二，相合很容易。柔中之君得刚中之臣，其合如咬软肉般容易——前往无阻。", "en": "You're in the place of honor, soft and centered, reaching down to the second line — union comes easily. A soft-centered ruler with a strong-centered minister, their joining is as easy as biting tender meat. Going forward meets no block.", "ja": "尊い位にいて、柔らかく中を得て九二に応じる。その合いは極めて容易。柔中の君が剛中の臣を得れば、その合うことは柔らかな肉を噛むよう。行く先に阻むものなし。"},
  "38-5": {"zh": "你到了卦的顶，是睽的极点，疑心生出妄见。疑到极点就无中生有——能放下疑心，所疑的其实都是亲近的人。", "en": "You're at the top of the hexagram, Kui at its extreme — suspicion breeding illusions. At the peak of doubt, you conjure something from nothing. Let the doubt go and those you suspected turn out to be your kin.", "ja": "卦の頂点にいて、睽の極。疑い心から妄った見方が生じる。疑いが極まれば無から有を作る。疑いを解ければ、疑った者たちは皆みずからの親だった。"},
  # 39 蹇
  "39-0": {"zh": "你在最底下，是蹇的开始，前往遇险，回来反得其所。时机不可前进就止——止而能自守，反而得到称誉。", "en": "You're at the bottom, the start of Jian — going meets danger, returning finds your place. When the time forbids going, stop. Stopping and keeping yourself brings praise instead.", "ja": "一番下にいて、蹇の初め。行けば険に遇い、来れば所を得る。時が進むことを許さなければ止む。止まって自らを守れば、かえって称賛を得る。"},
  "39-1": {"zh": "你在下卦正中，柔顺得正而应九五，冒蹇去救君主。处蹇而尽臣节，不是为了自身——忘身赴难，是忠的最高。", "en": "You're at the center of the lower trigram, soft and proper, matched with the fifth line, braving hardship to save your ruler. In Jian, fulfilling a minister's duty isn't for yourself. Forgetting yourself to help — that's the height of loyalty.", "ja": "下卦の中央にいて、柔らかく正しく九五に応じ、蹇を踏んで君を救う。蹇にあって臣の節を尽くすのは、自分のためではない。身を忘れて救う——これが忠の極みだ。"},
  "39-2": {"zh": "你在下卦最上面，刚正而前往就入险，返回反得所安。往险而返于内，是知止的人——下面两个阴爻，是可依靠的。", "en": "You're at the top of the lower trigram — rigid and upright — going meets danger, returning finds peace. Going to danger and coming back inside is knowing when to stop. The two yin below are whom you can rely on.", "ja": "下卦の最上部にいて、剛正で行けば険に入り、返れば安きを得る。険へ行って内へ返るのは、止まることを知る者だ。下の二つの陰が、頼れるところだ。"},
  "39-3": {"zh": "你在上卦下面，柔顺得正而前往就蹇，回来就连于九三。柔弱不足以独济，能连于刚就有为——连，就是合力。", "en": "You're below the upper trigram, soft and proper — going means hardship, returning joins the third line. Too soft to manage alone, but joining the strong lets you act. Joining means uniting strength.", "ja": "上卦の下にいて、柔らかく正しく行けば蹇み、来れば九三に連なる。柔では独りで救えないが、剛に連なれば何か成せる。連なるとは、力を合わせることだ。"},
  "39-4": {"zh": "你身居尊位，刚健中正却陷在险中，是蹇的主爻。大蹇之时，不是一人能救——刚中而能招来同志，蹇就能解。", "en": "You're in the place of honor, strong and centered yet trapped in danger — the main line of Jian. In a great difficulty, one person can't save it. Strong and centered, gathering your allies, the difficulty can be resolved.", "ja": "尊い位にいて、剛中で険に陷り、蹇の主爻となる。大いな蹇の時、一人では救えない。剛中で同志を招ければ、蹇は解ける。"},
  "39-5": {"zh": "你到了卦的顶，蹇的终点，前往更蹇，回来反得大。蹇极则反——就近九五之刚，就能有成，这叫来硕。", "en": "You're at the top of the hexagram, Jian at its end — going deepens difficulty, returning gains greatly. When Jian peaks it reverses. Draw near the fifth line's strength and you can achieve — that's the great return.", "ja": "卦の頂点にいて、蹇の終わり。行けばさらに蹇み、来れば大きく得る。蹇が極まれば返る。九五の剛に就けば成すことができ、これを来硕という。"},
  # 40 解
  "40-0": {"zh": "你在最底下，是解的开始，险难刚解，柔顺而不妄动。难刚解时，不可再做别的——静下来安守，就能无过。", "en": "You're at the bottom, the start of Xie — difficulty just released, soft and not acting. When trouble has just eased, don't start new ventures. Settle and keep still, and you'll avoid fault.", "ja": "一番下にいて、解の初め。険難が解けたばかりで、柔らかく動かない。難が解けたばかりの時、別の事をしてはならない。静かに安んじれば、過ちはない。"},
  "40-1": {"zh": "你在下卦正中，刚健中正而解难，去掉邪媚。解难先去邪——刚直而能中，所去得当、所存者正。", "en": "You're at the center of the lower trigram, strong and centered, resolving difficulty and removing the crooked. To resolve trouble, remove the evil first. Upright and centered, you cut off what should go and keep what's right.", "ja": "下卦の中央にいて、剛中で難を解き、邪な者を除く。難を解くにはまず邪を除くこと。剛直で中を得れば、除くものは当たり、残すものは正しい。"},
  "40-2": {"zh": "你在下卦最上面，不中不正，以小人而占了君子的位子。处非其分，就招人夺取——德不称位，是自己招患。", "en": "You're at the top of the lower trigram — off-center and improper — a small man occupying a gentleman's place. Out of your station invites others to take it. Virtue not matching position brings trouble on yourself.", "ja": "下卦の最上部にいて、中も正も外れ、小人が君子の器に乗る。分にあらざれば人に奪われる。徳が位に釣り合わないのは、自ら患いを招くことだ。"},
  "40-3": {"zh": "你在上卦下面，解开小的牵系，而后朋友同类才可信。解去私系，同志就来——牵系不去，信任就立不起来。", "en": "You're below the upper trigram, loosening small attachments, then allies can be trusted. Shed private ties and like-minded people come. If attachments remain, trust can't be established.", "ja": "上卦の下にいて、小さな執われを解き、それから朋類が信じられる。私的な執わりを解けば同志が来る。執わりを去らなければ、信は立たない。"},
  "40-4": {"zh": "你在尊位，柔和中正而解天下之难，用信服人。解难以诚服人，连小人也会信——诚信所及，难自然解开。", "en": "You're in the place of honor, soft and centered, resolving the world's difficulties, winning people with trust. Resolve trouble by winning with sincerity — even small men believe. Where trust reaches, difficulty dissolves.", "ja": "尊い位にいて、柔らかく中を得て天下の難を解き、信で人を服す。難を解くには誠で人を服させれば、小人も信じる。信の及ぶところ、難は自ずと解ける。"},
  "40-5": {"zh": "你到了卦的顶，是解的终点，除掉残害中最甚的。难既解，就除其根——去掉居高作害的，所往无阻。", "en": "You're at the top of the hexagram, Xie at its end, removing the worst of the harmful. Once difficulty is resolved, remove its root. Take away the one harming from on high, and nowhere you go is blocked.", "ja": "卦の頂点にいて、解の終わり。害の中でも最も甚だしい者を除く。難が解けたなら、その根を除く。高い所で害をなす者を去れば、行く先に阻むものなし。"},
  # 41 损
  "41-0": {"zh": "你在最底下，是损的开始，办事快、赶快前往，斟酌着自我减损。损己益人贵在快——快而不失分寸，其损才能持续。", "en": "You're at the bottom, the start of Sun — acting promptly, hurrying on, weighing how to reduce yourself. Reducing self to benefit others values speed. Quick yet measured, your reduction can continue.", "ja": "一番下にいて、損の初め。事を済ませて速く往き、具合を酌んで自らを減らす。己を損して人を益すのは速さが肝心。速くても節を失わなければ、その損は続けられる。"},
  "41-1": {"zh": "你在下卦正中，刚健中正而不损己去迁就人。刚中之德不可自损——守正不妄进，这是益而不是损。", "en": "You're at the center of the lower trigram, strong and centered, not reducing yourself to comply with others. Strong-centered virtue must not be diminished. Keep rightness and don't rush ahead — that's increase, not decrease.", "ja": "下卦の中央にいて、剛中で己を損して人に従わない。剛中の徳は自ら損してはならない。正を守って妄りに進まない——これは損ではなく益だ。"},
  "41-2": {"zh": "你在下卦最上面，三人则有余，一人则不足。两相与是天地之常——三人就生疑，一人就求配，损有余以成双。", "en": "You're at the top of the lower trigram — three means surplus, one means shortage. Two joining is heaven and earth's norm. Three breeds doubt, one seeks a mate — reduce the surplus to make a pair.", "ja": "下卦の最上部にいて、三人なら余り、一人なら足りない。二つが与え合うのは天地の常だ。三人は疑いを生み、一人は対を求める。余りを損して二つを成す。"},
  "41-3": {"zh": "你在上卦下面，柔顺得正而损所当损。损其不善，如同治病——去得快，喜也来得快。", "en": "You're below the upper trigram, soft and proper, reducing what should be reduced. Cutting out the bad is like removing a sickness — the faster it goes, the quicker the relief.", "ja": "上卦の下にいて、柔らかく正しく損むべきものを損す。善くないものを除くのは病を取るようなもの。早く去れば、喜びも早い。"},
  "41-4": {"zh": "你在尊位，柔和中正而虚己以受天下之益。自损而受人之益，益者自来——虚心就不违背所给。", "en": "You're in the place of honor, soft and centered, emptying yourself to receive the world's increase. Reduce yourself and accept others' help — helpers come on their own. An empty center doesn't reject what's given.", "ja": "尊い位にいて、柔らかく中を得て己を虚しくし、天下の益を受ける。自ら損して人の益を受ければ、益する者は自ら来る。虚な心は与えられるものを拒まない。"},
  "41-5": {"zh": "你到了卦的顶，是损的终点，不损己也可以益人。损到极而不损，是损道之成——有其德就可以前往，得人而不私其家。", "en": "You're at the top of the hexagram, Sun at its end — without reducing yourself you can benefit others. At the peak of reducing, not reducing is Sun's completion. With this virtue you can go, gaining people without keeping them private.", "ja": "卦の頂点にいて、損の終わり。己を損さずに人を益せる。損の極で損さないのは、損の道の成就だ。その徳があれば往ける。人を得てもその家を私有しない。"},
  # 42 益
  "42-0": {"zh": "你在最底下，是益的开始，受上面之益而可以大有作为。得在上者的益，可任大事——但必尽善，才能免过。", "en": "You're at the bottom, the start of Yi — receiving benefit from above, able to accomplish greatly. Gaining help from those above, you can undertake great things. But only by being fully good can you avoid fault.", "ja": "一番下にいて、益の初め。上からの益を受け、大いに事を成せる。上の者から益を得れば大事を任ぜられる。ただ善を尽くして初めて過ちを免れる。"},
  "42-1": {"zh": "你在下卦正中，柔顺得正而虚心，益自外来。虚心守常，益者自来不去——诚足以享神，这是受益之本。", "en": "You're at the center of the lower trigram, soft, proper and empty within — increase comes from outside. Empty and keeping the constant, increase comes and stays. Sincerity can even serve the divine — that's the root of receiving.", "ja": "下卦の中央にいて、柔らかく正しく心を虚しくし、益は外から来る。虚しく常を守れば、益する者は来て去らない。誠は神に供えるに足る——これが益を受ける本だ。"},
  "42-2": {"zh": "你在下卦最上面，不中不正，把益人之道用在患难上。以所受之益去济人之急，是用之正——行之以诚，人就信。", "en": "You're at the top of the lower trigram — off-center and improper — applying the way of benefit in times of hardship. Using what you received to relieve others' urgency is the right use. Act with sincerity and people trust you.", "ja": "下卦の最上部にいて、中も正も外れ、益する道を患難に用いる。受けた益で人の急を救うのは、その用い方が正しい。誠をもって行えば、人は信じる。"},
  "42-3": {"zh": "你在上卦下面，柔顺得正而依于九五，奉行所告。有所为就告于上而从而行之——依君行大事，是益之大。", "en": "You're below the upper trigram, soft and proper, relying on the fifth line and carrying out its instruction. When you act, report above and follow. Relying on your ruler for great deeds is the greatest Yi.", "ja": "上卦の下にいて、柔らかく正しく九五に依り、告げられたことを行う。事を為すなら上に告げて従う。君に依って大事を行う——これが益の大なるものだ。"},
  "42-4": {"zh": "你身居尊位，刚健中正而有惠下之心，诚相感。以诚惠下，下也以诚报——惠发自心，其应就大。", "en": "You're in the place of honor, strong and centered, with a heart to benefit those below, responding in sincerity. Benefit from the heart, and they repay in kind. Kindness from the heart meets a great response.", "ja": "尊い位にいて、剛中で下を恵む心があり、誠が感応し合う。誠で下を恵めば、下も誠で報いる。恵みが心から出れば、その応えは大きい。"},
  "42-5": {"zh": "你到了卦的顶，是益的终点，求益不已而没人给你。求益无厌，人就反过来攻击——立心不恒，其求必穷。", "en": "You're at the top of the hexagram, Yi at its end — seeking increase endlessly and no one gives. Insatiable seeking makes people turn on you. A heart that doesn't last will exhaust its seeking.", "ja": "卦の頂点にいて、益の終わり。益を求め続けても、誰も与えない。益を求めて際限がなければ、人はかえって撃つ。立てた心が続かないなら、その求めは必ず尽きる。"},
  # 43 夬
  "43-0": {"zh": "你在最底下，是夬的开始，以刚在下决断，力气还不够。决断贵在量力——力不足就贸然前往，咎由自取。", "en": "You're at the bottom, the start of Guai — deciding with strength below, but not yet strong enough. Decision values knowing your strength. If strength is short yet you rush ahead, the blame is yours.", "ja": "一番下にいて、夬の初め。剛で下から決するが、力はまだ足りない。決するのは力を量ることが肝心。力が足りずに急いで往けば、咎は自ら招くものだ。"},
  "43-1": {"zh": "你在下卦正中，刚健中正而知戒，虽有变也不忧。能戒就可不忧——中而有备，即使突发之变也不足为患。", "en": "You're at the center of the lower trigram, strong and centered and watchful — though change comes, you don't fear. Watchfulness removes fear. Centered and prepared, even sudden change is no trouble.", "ja": "下卦の中央にいて、剛中で戒めを知り、変富有っても憂えない。戒められれば憂えずに済む。中で備えがあれば、突然の変も患いにはならない。"},
  "43-2": {"zh": "你在下卦最上面，过刚而决于形色，决断太露。决而去之不可形于外——独行而暂与之和，其志固在去除。", "en": "You're at the top of the lower trigram — overly rigid, deciding in plain sight — too overt. Removing someone shouldn't show outwardly. Go alone but temporarily seem to agree; your aim stays fixed on removal.", "ja": "下卦の最上部にいて、剛が過ぎて色に決し、その決断が露わすぎる。決して除くのは外に形してはならない。独り行ってしばらく和ぶふりをしても、志は除くことにある。"},
  "43-3": {"zh": "你在上卦下面，不中不正，进不能、决不果。居不安而进不能，是听不明——能牵以随众，悔就可消。", "en": "You're below the upper trigram — off-center and improper — unable to advance, irresolute. Unsettled and unable to go means poor judgment. If you can follow the crowd, regret can disappear.", "ja": "上卦の下にいて、中も正も外れ、進めず決められない。居所が安まらず進めないのは、見聞きが明らかでない。衆に牽かれて従えば、悔いは消える。"},
  "43-4": {"zh": "你身居尊位，刚健中正而决所当决，行之以中。决小人不可过暴——用中道去决，不激而事可成。", "en": "You're in the place of honor, strong and centered, deciding what should be decided, acting with the middle way. Deciding against the small men shouldn't be too violent. Decide through the mean — no backlash, and the task gets done.", "ja": "尊い位にいて、剛中で決すべき者を決し、中道で行う。小人を決するのに暴しすぎてはならない。中道で決すれば、反発を招かず事が成る。"},
  "43-5": {"zh": "你到了卦的顶，是夬的终点，所决者已去，无可号呼。决之既尽，阴无所容——其终之穷，是理之必至。", "en": "You're at the top of the hexagram, Guai at its end — what was decided is gone, no more crying out. Once decision is complete, the yin has no place. Its end at exhaustion is inevitably how things go.", "ja": "卦の頂点にいて、夬の終わり。決すべき者は去り、叫ぶ者もいない。決め尽くされれば、陰は容れる所を失う。その終わりの穷まりは、理の必ず至るところだ。"},
  # 44 姤
  "44-0": {"zh": "你在最底下，是姤的开始，一阴始生，用刚止住。阴初生时微弱易制——制之于早，就不至于盛了才难图。", "en": "You're at the bottom, the start of Gou — one yin beginning, stopped by strength. When yin first arises it's small and easy to check. Check it early and it won't grow strong before becoming hard to handle.", "ja": "一番下にいて、姤の初め。一つの陰が生まれ始め、剛でこれを止める。陰が生まれたばかりは微かで制しやすい。早めに制すれば、盛んになってから計りにくくなることはない。"},
  "44-1": {"zh": "你在下卦正中，刚健中正而制初六之阴，制在自己。阴在我所制之内，可以无过——因不广及，故不利宾。", "en": "You're at the center of the lower trigram, strong and centered, restraining the first yin — control lies with you. With the yin within your control, you avoid fault. Because it doesn't extend widely, it's not favorable to entertain guests.", "ja": "下卦の中央にいて、剛中で初六の陰を制する。制するのは自分次第。陰が己の制する内にあれば過ちはない。広く及ばないので、宾をもてなすのは利しくない。"},
  "44-2": {"zh": "你在下卦最上面，过刚而不中，无所遇而不安。处姤之时而无所得，行不安——刚而不中，故不能制其阴。", "en": "You're at the top of the lower trigram — overly rigid, off-center — meeting nothing and unsettled. In Gou, gaining nothing leaves your movement uneasy. Rigid and off-center, you can't check the yin.", "ja": "下卦の最上部にいて、剛が過ぎて中を外れ、遇うものがなく安まない。姤の時に得る所がなければ、その行いは落ち着かない。剛で中を外れているので、その陰を制せない。"},
  "44-3": {"zh": "你在上卦下面，与初六正应却失其制。失其所制，民不为用——失民而想有为，变故就自己起来。", "en": "You're below the upper trigram, properly matched with the first yin but losing control. Losing control, people won't serve. Having lost them yet wanting to act, trouble arises of itself.", "ja": "上卦の下にいて、初六と正しく応じるが制を失う。制する所を失えば、民は使われない。民を失って何か成そうとすれば、変は自ら起こる。"},
  "44-4": {"zh": "你身居尊位，刚健中正而下包初六之阴，美在其中。以刚中之德包其微阴，不显其美——时既至，其应自来。", "en": "You're in the place of honor, strong and centered, embracing the first yin below — beauty within. With strong-centered virtue you enfold the tiny yin without displaying your beauty. When the time comes, response comes on its own.", "ja": "尊い位にいて、剛中で下の初六の陰を包む。美は内にある。剛中の徳で微かな陰を包み、その美を現さない。時が来れば、応えは自ら来る。"},
  "44-5": {"zh": "你到了卦的顶，是姤的终点，刚而在上，无所与遇。处遇之极而无所遇，是势之穷——然刚而不妄，故可无过。", "en": "You're at the top of the hexagram, Gou at its end — strong above, meeting nothing. At the extreme of encounter with no encounter, your force is spent. But strong and not rash, you can avoid fault.", "ja": "卦の頂点にいて、姤の終わり。剛が上にあり、遇う者がない。遇いの極で遇うものがないのは、勢いが尽きたこと。ただ剛で妄りがないので、過ちは免れる。"},
}
